# Project the public-domain Natural Earth land polygons. No political borders.
geo=json.loads((B/'countries.geojson').read_text(encoding='utf-8'));paths=[]
for f in geo['features']:
 polys=f['geometry']['coordinates'] if f['geometry']['type']=='MultiPolygon' else [f['geometry']['coordinates']]
 for poly in polys:
  ring=poly[0]
  if max(p[0] for p in ring)<20 or min(p[0] for p in ring)>60 or max(p[1] for p in ring)<10 or min(p[1] for p in ring)>42:continue
  paths.append('M'+'L'.join(f'{(lon-20)*21:.1f},{(42-lat)*17.5:.1f}' for lon,lat,*_ in ring)+'Z')
parables=[]
def parable(id,title,ref,area,summary,nodes,question,answer,distractors,reflection):
 options=[answer]+distractors;random.Random(id).shuffle(options)
 parables.append(dict(id=id,title=title,passage=passage(ref),area=area,summary=summary,nodes=[dict(label=a,detail=b) for a,b in nodes],question=question,options=options,answer=options.index(answer),reflection=reflection,commentaryUrl=commentary(ref.split('-')[0])))
parable('kindled-fire','A fire and the loss of light','2:17-18','Guidance','Al-Tafsir al-Muyassar compares outwardly professed faith followed by rejection with light that is lost in darkness.', [('Kindled fire','The opening image provides light around the person.'),('Light removed','The passage then describes the removal of light.'),('Darkness','The comparison ends with people unable to see.')], 'What changes in the image?','Light gives way to darkness.',['A garden becomes a river.','A mountain becomes dust.','A seed produces seven ears.'],'Notice the movement from illumination to darkness. What do the surrounding verses add?')
parable('storm','Darkness, thunder, and lightning','2:19-20','Guidance','Al-Tafsir al-Muyassar describes a comparison involving fear, intermittent light, and hesitation in response to truth.', [('Storm','Rain, darkness, thunder, and lightning form the image.'),('A flash of light','They walk when the lightning lights the way.'),('Darkness returns','They stand still when darkness falls.')], 'When do they walk in the image?','When the lightning gives them light.',['Only after dawn','When the river dries','When the tree bears fruit'],'Read how movement depends on the flash of light. Keep this observation separate from judging other people.')
