def save(slug,data):
 app=ROOT/'apps'/slug;p=app/'src/data/content.json';p.write_text(json.dumps(data,ensure_ascii=False,indent=2)+'\n',encoding='utf-8');sources={}
 def add(label,url,kind='Quran passage',note=''):
  if url:sources[url]=dict(label=label,url=url,kind=kind,note=note)
 def collect(v):
  if isinstance(v,list):
   for x in v:collect(x)
  elif isinstance(v,dict):
   if 'translationUrl' in v:add('Quran '+v['ref']+' · Pickthall',v['translationUrl'])
   if 'commentaryUrl' in v:add('Al-Tafsir al-Muyassar',v['commentaryUrl'],'Arabic commentary','Original concise English paraphrases are labeled in the app.')
   if 'secondCommentaryUrl' in v:add('Al-Jalalayn · 24:35',v['secondCommentaryUrl'],'Arabic commentary','Second source for the Light verse.')
   if v.get('geoUrl'):add(v['geoLabel'],v['geoUrl'],'Geographical data',v.get('note',''))
   if 'sources' in v:
    for s in v['sources']:add(s['label'],s['url'],s.get('kind','Hadith'),s.get('note',''))
   for x in v.values():collect(x)
 collect(data)
 if slug=='places-in-the-quran':add('Natural Earth · public-domain map data','https://www.naturalearthdata.com/about/terms-of-use/','Map attribution','Land polygons projected and clipped for a regional orientation map. No political borders are drawn.')
 (app/'src/data/sources.json').write_text(json.dumps(list(sources.values()),ensure_ascii=False,indent=2),encoding='utf-8');additional=json.loads((B/'provenance.json').read_text(encoding='utf-8'))
 (app/'src/data/provenance.json').write_text(json.dumps({**prov,'app':slug,'appContentSha256':hashlib.sha256(p.read_bytes()).hexdigest(),'batch3Commentary':additional},indent=2),encoding='utf-8')
 print(slug,len(sources))
if __name__=='__main__':
 for slug,data in bundles.items():save(slug,data)
